//! TPC-DS on a cluster: the same data and the same 24 queries as the single-node `tpc ds` example, run on a cluster of shard
//! nodes (in this process, talking Arrow Flight over TCP) and on one engine; the answers must agree.
//!
//!   (with `--config cluster.json` it connects to shard nodes that are already running)
//!   cargo run --release -p tsql-control --example tpcds_cluster [-- --sf 0.01 --shards 3]
//!
//! The data is generated by the single-node example's generator into one engine, then copied through the control node
//! (so every row is routed by its shard key), then each query runs on both and the answers are compared. The table shows
//! how the cluster ran each query (`scatter` = every shard works on its rows and the control node merges; `gather` = the
//! tables are copied to the control node, kept until they change; `route` = one shard) and the times of both. The exit
//! status is non-zero when an answer differs or a query fails.
#[path = "../../../../examples/tpc/ds.rs"]
mod ds;
#[path = "../../../../examples/tpc/util.rs"]
mod util;

use std::time::Instant;
use tsql_control::Cluster;
use tsql_server::ast::{Expr, Insert, InsertSrc, Stmt, Target};
use tsql_server::{Server, Value};
use tsql_shared_ces::{ClusterConfig, ShardInfo};
use tsql_storage::{spawn, ShardNode};

#[cfg(feature = "fast-alloc")]
#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

/// The text of a `const NAME: &str = "..."` of the single-node example (one source of truth for the schema).
fn schema_const(name: &str) -> String {
    const SRC: &str = include_str!("../../../../examples/tpc/ds.rs");
    let start = SRC.find(&format!("const {}: &str = \"", name)).expect("constant not found") + format!("const {}: &str = \"", name).len();
    let end = start + SRC[start..].find("\";").expect("end of constant");
    SRC[start..end].to_string()
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let flag = |name: &str| args.iter().position(|a| a == name).and_then(|i| args.get(i + 1)).and_then(|v| v.parse::<f64>().ok());
    let sf = flag("--sf").unwrap_or(0.01);
    let nshards = flag("--shards").unwrap_or(3.0) as usize;

    println!("== TPC-DS on {} shards (scale factor {}) ==", nshards, sf);
    let single = Server::new();
    let mut oc = single.connect();
    let t = Instant::now();
    let data = ds::load(&mut oc, sf);
    println!("single node loaded in {:.2}s", t.elapsed().as_secs_f64());

    let rt = tokio::runtime::Runtime::new().unwrap();
    let mut shards = vec![];
    // with `--config cluster.json` the shard nodes are already running (on other machines); otherwise they start in this process
    let cfg = match args.iter().position(|a| a == "--config").and_then(|i| args.get(i + 1)) {
        Some(path) => ClusterConfig::load(path).unwrap_or_else(|e| {
            eprintln!("{}", e);
            std::process::exit(2)
        }),
        None => {
            for i in 0..nshards {
                shards.push(rt.block_on(spawn(ShardNode::new(i as u32, Server::new()), "127.0.0.1:0".parse().unwrap())).unwrap());
            }
            ClusterConfig { shards: shards.iter().enumerate().map(|(i, s)| ShardInfo { id: i as u32, addr: s.addr.to_string() }).collect() }
        }
    };
    let nshards = cfg.shards.len();
    let cluster = Cluster::connect(&cfg).unwrap();
    let mut cs = cluster.session();
    // (a cluster that was used before has the tables of its last run)
    for t in ["region", "nation", "supplier", "customer", "part", "partsupp", "orders", "lineitem", "date_dim", "time_dim", "item", "customer_demographics", "household_demographics", "customer_address", "store", "promotion", "warehouse", "store_sales", "store_returns", "catalog_sales", "web_sales", "inventory"] {
        let _ = cs.execute(&format!("DROP TABLE IF EXISTS {}", t));
    }

    let t = Instant::now();
    let schema = schema_const("SCHEMA");
    let mut tables = vec![];
    for stmt in schema.split(';').map(str::trim).filter(|s| !s.is_empty()) {
        let r = cs.execute(stmt);
        if let Some(e) = r.first_error() {
            panic!("{}: {}", stmt, e);
        }
        if let Some(name) = stmt.strip_prefix("CREATE TABLE ").and_then(|s| s.split_whitespace().next()) {
            tables.push(name.to_string());
        }
    }
    // every table is sharded on the first column of its primary key (nothing is replicated or placed for the benchmark)
    for stmt in schema_const("INDEXES").split(';').map(str::trim).filter(|s| !s.is_empty()) {
        let r = cs.execute(stmt);
        if let Some(e) = r.first_error() {
            panic!("{}: {}", stmt, e);
        }
    }
    let mut copied = 0usize;
    for table in &tables {
        let rows = oc.query(&format!("SELECT * FROM {}", table)).unwrap();
        copied += rows.len();
        for chunk in rows.chunks(500) {
            let values: Vec<Vec<Expr>> = chunk.iter().map(|r: &Vec<Value>| r.iter().cloned().map(Expr::Lit).collect()).collect();
            let ins = Stmt::Insert(Box::new(Insert { ctes: vec![], target: Target::Table(vec![table.clone()]), cols: None, output: None, src: InsertSrc::Values(values), top: None }));
            let r = cs.execute_stmts(&[ins]);
            if let Some(e) = r.first_error() {
                panic!("loading {}: {}", table, e);
            }
        }
    }
    println!("cluster loaded ({} rows copied through the control node) in {:.2}s", copied, t.elapsed().as_secs_f64());

    let mut failures = 0;
    let (mut single_total, mut cluster_total) = (0.0, 0.0);
    println!("{:<40} {:>9} {:>9}  {:<34} answer", "query", "single", "cluster", "plan");
    for (name, sql) in ds::queries() {
        // (`--only Q16,Q22`: just those queries, each with its whole plan)
        if let Some(i) = args.iter().position(|a| a == "--only") {
            let wanted = args.get(i + 1).cloned().unwrap_or_default();
            if !wanted.split(',').any(|w| name.split_whitespace().next().map(|n| n.eq_ignore_ascii_case(w.trim())).unwrap_or(false)) {
                continue;
            }
        }
        let (a, ta) = util::timed(&mut oc, &sql);
        let t = Instant::now();
        let res = cs.execute(&sql);
        let tb = t.elapsed().as_secs_f64();
        let plan = cs.last_plan().iter().map(|p| p.split_whitespace().next().unwrap_or("").trim_end_matches(':').to_string()).collect::<Vec<_>>().join(",");
        single_total += ta;
        cluster_total += tb;
        let verdict = match (&a, res.first_error()) {
            (Ok(expected), None) => {
                let got: Vec<Vec<String>> = res.resultsets().first().map(|rs| rs.rows.iter().map(|row| row.iter().map(|v| v.to_string()).collect()).collect()).unwrap_or_default();
                match util::compare_rows(&got, expected) {
                    None => match ds::check(&data, &name, &got) {
                        Some(Ok(())) => "same (and checked against the generated rows)".to_string(),
                        Some(Err(e)) => {
                            failures += 1;
                            format!("WRONG against the generated rows: {}", e)
                        }
                        None => "same".to_string(),
                    },
                    Some(diff) => {
                        failures += 1;
                        format!("DIFFERENT: {}", diff)
                    }
                }
            }
            (Err(e), Some(ce)) if e.contains(&ce.message) || ce.message.contains(e.as_str()) => "same error".to_string(),
            (Ok(_), Some(ce)) => {
                failures += 1;
                format!("CLUSTER ERROR: {}", ce)
            }
            (Err(e), None) => {
                failures += 1;
                format!("single node failed: {}", e)
            }
            (Err(_), Some(_)) => "both fail".to_string(),
        };
        println!("{:<40} {:>8.3}s {:>8.3}s  {:<34} {}", name, ta, tb, plan, verdict);
        if std::env::var("PLAN_ALL").is_ok() || args.iter().any(|a| a == "--only") {
            for l in cs.last_plan() {
                println!("      plan: {}", l);
            }
        }
    }
    println!("total: single {:.2}s, cluster {:.2}s, {} problem(s)", single_total, cluster_total, failures);
    for s in shards {
        rt.block_on(s.shutdown());
    }
    std::process::exit(if failures == 0 { 0 } else { 1 });
}
